// Titanic raw-pointer adapter: FlashInfer v0.7.3 SM120 sparse-MLA DeepSeek-V4.1 BF16 split decode with FP32
// partials (generated by make_decode.py from the vendored, unmodified upstream headers; Apache-2.0 / BSD-3-Clause).
// Caches: main V4.1 (528 B/token, 64-token pages) and extra V4.1-FP4 (288 B/token, 64-token pages), as written by
// the V4.1 store kernels. Numerics: both caches dequantized exactly to bf16; bf16 QK and PV MMAs with fp32
// accumulation; fp32 normalized partials and a log2 LSE per split; the merge folds in the attention sink and
// writes bf16 output and the final log2 LSE (sink included), the convention the prefill entry point also uses.
#include <cuda_runtime.h>
#include <flashinfer/attention/sparse_mla_sm120/kernels/dsv41_bf16/decode.cuh>
#include <flashinfer/attention/sparse_mla_sm120/execution/merge.cuh>

namespace flashinfer::sparse_mla_sm120::kernels::dsv41_bf16 {
template <int NUM_HEADS, bool EXTRA_FP4, ModelType MT = ModelType::DSV4_1>
__global__ void __launch_bounds__(Dsv41Bf16Resources::BLOCK_THREADS, 1)
    titanic_dsv41_decode_fp32_kernel(
        const bf16* __restrict__ Q, const uint8_t* __restrict__ KV_cache,
        const int32_t* __restrict__ indices, float* __restrict__ mid_out,
        float* __restrict__ mid_lse, const int* __restrict__ topk_length_ptr,
        const uint8_t* __restrict__ extra_KV_cache, const int32_t* __restrict__ extra_indices,
        const int* __restrict__ extra_topk_length_ptr, int extra_topk, int pbs_extra,
        size_t extra_page_stride_bytes, int num_tokens, int num_heads, int topk,
        int scratch_split_stride, int chunks_per_block, float sm_scale, size_t page_stride_bytes,
        size_t indices_stride_elems, size_t extra_indices_stride_elems, int main_page_block_size) {
  using R = Dsv41Bf16Resources;
  using Geometry = R::Geometry;
  using Cache = Dsv41Bf16Cache<MT>;
  const int t = blockIdx.x, hs = blockIdx.y * R::HEADS_PER_CTA, split = blockIdx.z;
  const int qh = NUM_HEADS ? NUM_HEADS : num_heads;
  const int mh = NUM_HEADS ? NUM_HEADS : int(gridDim.y) * R::HEADS_PER_CTA;
  const int vh = min(R::HEADS_PER_CTA, qh - hs);
  const int tidx = threadIdx.x, warp = tidx / R::WARP_THREADS, lane = tidx % R::WARP_THREADS;
  const int gid = lane / 4, tid = lane % 4;
  if (t >= num_tokens) return;
  int len = topk_length_ptr ? topk_length_ptr[t] : topk;
  len = max(0, min(topk, len));
  int elen = extra_KV_cache ? (extra_topk_length_ptr ? extra_topk_length_ptr[t] : extra_topk) : 0;
  elen = max(0, min(extra_topk, elen));
  const int main_chunks = (len + R::CANDIDATES - 1) / R::CANDIDATES;
  const int chunks = main_chunks + (elen + R::CANDIDATES - 1) / R::CANDIDATES;
  const int lo = split * chunks_per_block, hi = min(lo + chunks_per_block, chunks);
  if (lo >= chunks) {
    if (tidx < vh) mid_lse[((size_t)t * mh + hs + tidx) * scratch_split_stride + split] = -1e30f;
    return;
  }
  extern __shared__ __align__(16) unsigned char storage[];
  auto& sm = *reinterpret_cast<Dsv41Bf16Smem*>(storage);
  for (int i = tidx; i < R::HEADS_PER_CTA * R::QK_VECTORS; i += R::BLOCK_THREADS) {
    const int h = i / R::QK_VECTORS, d = i % R::QK_VECTORS * R::VECTOR_ELEMS;
    uint4 data =
        h < vh ? *reinterpret_cast<const uint4*>(Q + ((size_t)t * qh + hs + h) * Geometry::D_QK + d)
               : make_uint4(0, 0, 0, 0);
    *reinterpret_cast<uint4*>(&sm.q[h][d]) = data;
  }
  float acc[R::PV_TILES_PER_WARP][4] = {};
  float m[2] = {-1e30f, -1e30f}, sum[2] = {0.f, 0.f};
  for (int chunk = lo; chunk < hi; ++chunk) {
    const bool extra = chunk >= main_chunks;
    const bool fp4 = EXTRA_FP4 && extra;
    const int start = (extra ? chunk - main_chunks : chunk) * R::CANDIDATES;
    const int n = extra ? elen : len, pbs = extra ? pbs_extra : main_page_block_size;
    const size_t stride = extra ? extra_page_stride_bytes : page_stride_bytes;
    const uint8_t* cache = extra ? extra_KV_cache : KV_cache;
    const int32_t* ix = extra ? extra_indices + (size_t)t * extra_indices_stride_elems
                              : indices + (size_t)t * indices_stride_elems;
    if (tidx < R::CANDIDATES) sm.valid[tidx] = start + tidx < n ? ix[start + tidx] : -1;
    __syncthreads();
    auto gather = [&](bool power_of_two) __attribute__((always_inline)) {
      for (int task = tidx; task < R::CANDIDATES * R::QK_VECTORS; task += R::BLOCK_THREADS) {
        const int row = task / R::QK_VECTORS, d = task % R::QK_VECTORS * R::VECTOR_ELEMS;
        const int index = sm.valid[row];
        uint64_t raw = 0;
        __nv_bfloat162 scale = __floats2bfloat162_rn(0.f, 0.f);
        if (index >= 0) {
          size_t slot;
          const uint8_t* base = Cache::locate(cache, index, pbs, stride, power_of_two, slot);
          const uint8_t* src = base + Cache::data_offset(fp4, slot) + (fp4 ? d / 2 : d);
          raw = fp4 ? uint64_t(*reinterpret_cast<const uint32_t*>(src))
                    : *reinterpret_cast<const uint64_t*>(src);
          const uint8_t sc =
              base[Cache::scale_offset(fp4, pbs, slot) +
                   d / (fp4 ? Dsv41Fp4Layout::SCALE_GROUP : Dsv41Fp8Layout::QUANT_TILE)];
          scale = decode_e4m3_or_ue8m0_scale_bf16(sc, fp4);
        }
        __nv_bfloat162 pairs[4];
#pragma unroll
        for (int j = 0; j < 4; ++j)
          pairs[j] = __hmul2(
              decode_e2m1_or_e4m3_pair_bf16(uint32_t(raw >> (j * (fp4 ? 8 : 16))), fp4), scale);
        *reinterpret_cast<uint4*>(&sm.kv[row][d]) = *reinterpret_cast<uint4*>(pairs);
      }
    };
    if (Cache::INLINE || (pbs & (pbs - 1)) == 0)
      gather(true);
    else
      gather(false);
    __syncthreads();
    float qk[4] = {};
#pragma unroll
    for (int k = 0; k < Geometry::D_QK; k += R::MMA_K) {
      uint32_t a0, a1, a2, a3;
      ldmatrix_load_A_bf16(a0, a1, a2, a3, &sm.q[0][k], R::QK_STRIDE_ELEMS, lane);
      const uint32_t b0 = *reinterpret_cast<uint32_t*>(&sm.kv[warp * 8 + gid][k + tid * 2]);
      const uint32_t b1 = *reinterpret_cast<uint32_t*>(&sm.kv[warp * 8 + gid][k + tid * 2 + 8]);
      auto r = mma_bf16_m16n8k16(a0, a1, a2, a3, b0, b1, qk[0], qk[1], qk[2], qk[3]);
      qk[0] = r.d0;
      qk[1] = r.d1;
      qk[2] = r.d2;
      qk[3] = r.d3;
    }
#pragma unroll
    for (int j = 0; j < 4; ++j)
      qk[j] = sm.valid[warp * 8 + tid * 2 + (j & 1)] >= 0 ? qk[j] * (sm_scale * LOG2E) : -1e30f;
    float mx[2] = {fmaxf(qk[0], qk[1]), fmaxf(qk[2], qk[3])};
#pragma unroll
    for (int s = 1; s <= 2; s *= 2) {
      mx[0] = fmaxf(mx[0], __shfl_xor_sync(0xffffffff, mx[0], s));
      mx[1] = fmaxf(mx[1], __shfl_xor_sync(0xffffffff, mx[1], s));
    }
    if (tid == 0) {
      sm.reduce[0][warp][gid] = mx[0];
      sm.reduce[0][warp][gid + 8] = mx[1];
    }
    __syncthreads();
    float alpha[2];
#pragma unroll
    for (int h = 0; h < 2; ++h) {
      float next = m[h];
#pragma unroll
      for (int w = 0; w < R::WARPS; ++w) next = fmaxf(next, sm.reduce[0][w][gid + h * 8]);
      alpha[h] = exp2f(m[h] - next);
      m[h] = next;
    }
    float p[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
      p[j] = sm.valid[warp * 8 + tid * 2 + (j & 1)] >= 0 ? exp2f(qk[j] - m[j / 2]) : 0.f;
      sm.p[gid + j / 2 * 8][warp * 8 + tid * 2 + (j & 1)] = __float2bfloat16_rn(p[j]);
    }
    float ps[2] = {p[0] + p[1], p[2] + p[3]};
#pragma unroll
    for (int s = 1; s <= 2; s *= 2) {
      ps[0] += __shfl_xor_sync(0xffffffff, ps[0], s);
      ps[1] += __shfl_xor_sync(0xffffffff, ps[1], s);
    }
    if (tid == 0) {
      sm.reduce[1][warp][gid] = ps[0];
      sm.reduce[1][warp][gid + 8] = ps[1];
    }
    __syncthreads();
#pragma unroll
    for (int h = 0; h < 2; ++h) {
      sum[h] *= alpha[h];
#pragma unroll
      for (int w = 0; w < R::WARPS; ++w) sum[h] += sm.reduce[1][w][gid + h * 8];
    }
#pragma unroll
    for (int v = 0; v < R::PV_TILES_PER_WARP; ++v) {
#pragma unroll
      for (int j = 0; j < 4; ++j) acc[v][j] *= alpha[j / 2];
    }
#pragma unroll
    for (int k = 0; k < R::CANDIDATES; k += R::MMA_K) {
      uint32_t a0, a1, a2, a3;
      ldmatrix_load_A_bf16(a0, a1, a2, a3, &sm.p[0][k], R::P_STRIDE_ELEMS, lane);
#pragma unroll
      for (int v = 0; v < R::PV_TILES_PER_WARP; ++v) {
        uint32_t b0, b1;
        const uint32_t addr = uint32_t(__cvta_generic_to_shared(
            &sm.kv[k + (lane & 15)][v * (R::WARPS * R::MMA_N) + warp * R::MMA_N]));
        asm volatile("ldmatrix.sync.aligned.m8n8.x2.trans.shared.b16 {%0,%1},[%2];"
                     : "=r"(b0), "=r"(b1)
                     : "r"(addr));
        auto r =
            mma_bf16_m16n8k16(a0, a1, a2, a3, b0, b1, acc[v][0], acc[v][1], acc[v][2], acc[v][3]);
        acc[v][0] = r.d0;
        acc[v][1] = r.d1;
        acc[v][2] = r.d2;
        acc[v][3] = r.d3;
      }
    }
    __syncthreads();
  }
#pragma unroll
  for (int h = 0; h < 2; ++h) {
    const int head = hs + gid + h * 8;
    if (head < qh) {
      const float inv = sum[h] > 0.f ? 1.f / sum[h] : 0.f;
      const size_t base =
          ((size_t)t * mh + head) * scratch_split_stride * Geometry::D_V + split * Geometry::D_V;
#pragma unroll
      for (int v = 0; v < R::PV_TILES_PER_WARP; ++v) {
        const int d = v * (R::WARPS * R::MMA_N) + warp * R::MMA_N + tid * 2;
        *reinterpret_cast<float2*>(mid_out + base + d) =
            make_float2(acc[v][h * 2] * inv, acc[v][h * 2 + 1] * inv);
      }
      if (warp == 0 && tid == 0)
        mid_lse[((size_t)t * mh + head) * scratch_split_stride + split] =
            sum[h] > 0.f ? log2f(sum[h]) + m[h] : -1e30f;
    }
  }
}


}  // namespace flashinfer::sparse_mla_sm120::kernels::dsv41_bf16

namespace flashinfer::sparse_mla_sm120 {
template <int NUM_HEADS, int D_V_VAL, int BLOCK_THREADS, int DIMS_PER_THREAD>
static __global__ void __launch_bounds__(BLOCK_THREADS, 8)
    titanic_dsv41_merge_fp32_kernel(const float* __restrict__ mid_out,
                                        const float* __restrict__ mid_lse,
                                        bf16* __restrict__ output, float* __restrict__ out_lse,
                                        const float* __restrict__ attn_sink, int num_tokens,
                                        int num_splits, int num_heads, int mid_heads,
                                        size_t stride_out_lse, float lse_scale) {
  static_assert(BLOCK_THREADS % 32 == 0, "BLOCK_THREADS must be multiple of 32");
  static_assert(DIMS_PER_THREAD % 8 == 0, "DIMS_PER_THREAD must be multiple of 8 (2 float4)");
  static_assert(BLOCK_THREADS * DIMS_PER_THREAD == D_V_VAL, "block must cover the full D_V row");
  constexpr int VECS_PER_THREAD = DIMS_PER_THREAD / 8;
  const int q_heads = (NUM_HEADS == 0) ? num_heads : NUM_HEADS;
  const int m_heads = (NUM_HEADS == 0) ? mid_heads : NUM_HEADS;

  const int t_idx = blockIdx.x;
  const int h = blockIdx.y;
  if (t_idx >= num_tokens || h >= q_heads) return;
  const int tid = threadIdx.x;

  extern __shared__ __align__(16) unsigned char merge_smem_raw[];
  float* sm_lse = reinterpret_cast<float*>(merge_smem_raw);
  __shared__ float sm_gmax;
  __shared__ float sm_inv_gsum;
  __shared__ float sm_glse;

  const float* lse_ptr = mid_lse + (size_t)t_idx * m_heads * num_splits + (size_t)h * num_splits;

  for (int sp = tid; sp < num_splits; sp += BLOCK_THREADS) {
    sm_lse[sp] = lse_ptr[sp];
  }
  __syncthreads();

  if (tid < 32) {
    float local_max = -1e30f;
    for (int sp = tid; sp < num_splits; sp += 32) {
      local_max = fmaxf(local_max, sm_lse[sp]);
    }
#pragma unroll
    for (int s = 16; s >= 1; s >>= 1) {
      local_max = fmaxf(local_max, __shfl_xor_sync(0xffffffff, local_max, s));
    }
    float gmax = (local_max > -1e29f) ? local_max : 0.f;
    float sink_log2 = 0.f;
    if (attn_sink != nullptr) {
      sink_log2 = __ldg(attn_sink + h) * LOG2E;
      gmax = local_max > -1e29f ? fmaxf(gmax, sink_log2) : sink_log2;
    }

    float local_sum = 0.f;
    for (int sp = tid; sp < num_splits; sp += 32) {
      float lse_sp = sm_lse[sp];
      if (lse_sp > -1e29f) local_sum += exp2f(lse_sp - gmax);
    }
#pragma unroll
    for (int s = 16; s >= 1; s >>= 1) {
      local_sum += __shfl_xor_sync(0xffffffff, local_sum, s);
    }
    if (tid == 0) {
      float total_sum = local_sum;
      if (attn_sink != nullptr) total_sum += exp2f(sink_log2 - gmax);
      sm_gmax = gmax;
      sm_inv_gsum = (total_sum > 0.f) ? (1.f / total_sum) : 0.f;
      sm_glse = (total_sum > 0.f) ? (log2f(total_sum) + gmax) : -INFINITY;
    }
  }
  __syncthreads();
  const float global_max = sm_gmax;
  const float inv_global_sum = sm_inv_gsum;

  const float* mid_base = mid_out + ((size_t)t_idx * m_heads + h) * (size_t)num_splits * D_V_VAL;
  bf16* out_ptr = output + ((size_t)t_idx * q_heads + h) * D_V_VAL;
  const int dim_base = tid * DIMS_PER_THREAD;

  float acc[DIMS_PER_THREAD];
#pragma unroll
  for (int d = 0; d < DIMS_PER_THREAD; d++) acc[d] = 0.f;

  for (int sp = 0; sp < num_splits; sp++) {
    float lse_sp = sm_lse[sp];
    if (lse_sp <= -1e29f) continue;
    const float weight = exp2f(lse_sp - global_max);
    const float* row_base = mid_base + (size_t)sp * D_V_VAL + dim_base;
#pragma unroll
    for (int v = 0; v < VECS_PER_THREAD; v++) {
#pragma unroll
      for (int p = 0; p < 2; p++) {
        const float4 f = *reinterpret_cast<const float4*>(row_base + v * 8 + p * 4);
        acc[v * 8 + p * 4 + 0] += weight * f.x;
        acc[v * 8 + p * 4 + 1] += weight * f.y;
        acc[v * 8 + p * 4 + 2] += weight * f.z;
        acc[v * 8 + p * 4 + 3] += weight * f.w;
      }
    }
  }

#pragma unroll
  for (int v = 0; v < VECS_PER_THREAD; v++) {
    uint4 packed;
    __nv_bfloat162* pairs = reinterpret_cast<__nv_bfloat162*>(&packed);
#pragma unroll
    for (int p = 0; p < 4; p++) {
      pairs[p] = __floats2bfloat162_rn(acc[v * 8 + p * 2 + 0] * inv_global_sum,
                                       acc[v * 8 + p * 2 + 1] * inv_global_sum);
    }
    *reinterpret_cast<uint4*>(out_ptr + dim_base + v * 8) = packed;
  }
  if (out_lse != nullptr && tid == 0) {
    out_lse[(size_t)t_idx * stride_out_lse + h] = scale_output_lse(sm_glse, lse_scale);
  }
}


}  // namespace flashinfer::sparse_mla_sm120

namespace fi = flashinfer::sparse_mla_sm120;

// Scratch: mid_out [rows][16][splits][512] fp32, then mid_lse [rows][16][splits] fp32.
extern "C" size_t ca_sparse_decode_scratch_bytes(int rows, int splits) {
  return (size_t)rows * 16 * splits * (512 + 1) * sizeof(float);
}
extern "C" int ca_sparse_decode_abi() { return 1; }
extern "C" int ca_sparse_decode(int rows, int extra_topk, int extra_pbs, float scale, const void* q, const void* kv,
                                size_t stride, const void* indices, void* output, void* lse, const void* lengths,
                                const void* sink, const void* extra_kv, size_t extra_stride,
                                const void* extra_indices, const void* extra_lengths, void* scratch,
                                size_t scratch_bytes, int splits, cudaStream_t stream) {
  constexpr int kHeads = 16, kMainTopk = 128, kPage = 64;
  using R = fi::kernels::dsv41_bf16::Dsv41Bf16Resources;
  static_assert(kHeads == R::HEADS_PER_CTA, "one head block per row");
  if (rows < 1 || rows > 4096 || !(scale > 0) || extra_topk < 0 || extra_topk > 1024 || extra_topk % 64 || !q ||
      !kv || !indices || !output || !lse || !lengths || !sink || !scratch || stride == 0 || splits < 1 || splits > 64)
    return -1;
  if (scratch_bytes < ca_sparse_decode_scratch_bytes(rows, splits)) return -5;
  const bool extra = extra_topk > 0;
  if (extra && (!extra_kv || !extra_indices || !extra_lengths || extra_pbs != kPage || extra_stride == 0)) return -3;
  if (!extra && (extra_kv || extra_indices || extra_lengths)) return -2;
  const int chunks = (kMainTopk + R::CANDIDATES - 1) / R::CANDIDATES + (extra_topk + R::CANDIDATES - 1) / R::CANDIDATES;
  const int cpb = (chunks + splits - 1) / splits;
  float* mid_out = static_cast<float*>(scratch);
  float* mid_lse = mid_out + (size_t)rows * kHeads * splits * 512;
  const int smem = (int)sizeof(fi::kernels::dsv41_bf16::Dsv41Bf16Smem);
  auto launch = [&](auto kernel) -> int {
    cudaError_t e = cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, smem);
    if (e != cudaSuccess) return (int)e;
    kernel<<<dim3(rows, 1, splits), dim3(R::BLOCK_THREADS), smem, stream>>>(
        static_cast<const __nv_bfloat16*>(q), static_cast<const uint8_t*>(kv), static_cast<const int32_t*>(indices),
        mid_out, mid_lse, static_cast<const int*>(lengths), static_cast<const uint8_t*>(extra_kv),
        static_cast<const int32_t*>(extra_indices), static_cast<const int*>(extra_lengths), extra_topk, kPage,
        extra_stride, rows, kHeads, kMainTopk, splits, cpb, scale, stride, (size_t)kMainTopk, (size_t)extra_topk,
        kPage);
    return (int)cudaGetLastError();
  };
  int r = extra ? launch(fi::kernels::dsv41_bf16::titanic_dsv41_decode_fp32_kernel<kHeads, true, ::ModelType::DSV4_1>)
                : launch(fi::kernels::dsv41_bf16::titanic_dsv41_decode_fp32_kernel<kHeads, false, ::ModelType::DSV4_1>);
  if (r) return r;
  constexpr int kMergeThreads = 64;
  fi::titanic_dsv41_merge_fp32_kernel<kHeads, 512, kMergeThreads, 512 / kMergeThreads>
      <<<dim3(rows, kHeads), dim3(kMergeThreads), (size_t)splits * sizeof(float), stream>>>(
          mid_out, mid_lse, static_cast<__nv_bfloat16*>(output), static_cast<float*>(lse),
          static_cast<const float*>(sink), rows, splits, kHeads, kHeads, (size_t)kHeads, 1.f);
  return (int)cudaGetLastError();
}
